from __future__ import annotations
from typing import Optional, Tuple, Union, List
import io
from PIL import Image, ImageTk

# --- CTk Import Handling ---
try:
    # for when running inside customtkinter package
    from .ctk_label import CTkLabel  # type: ignore
except ImportError:
    # fallback if running standalone
    import customtkinter as ctk
    CTkLabel = ctk.CTkLabel  # type: ignore


# --- Pillow compatibility ---
# Handle LANCZOS rename between Pillow versions
if hasattr(Image, "Resampling"):  # Pillow ≥ 9.1
    RESAMPLE_LANCZOS = Image.Resampling.LANCZOS
else:
    RESAMPLE_LANCZOS = Image.LANCZOS  # type: ignore # older Pillow fallback


class CTkGIF(CTkLabel):  # type: ignore
    """
    CustomTkinter-compatible widget to display and animate GIFs.
    """

    def __init__(
        self,
        master=None,
        source: Optional[Union[str, bytes, Image.Image]] = None,
        *,
        size: Optional[Tuple[int, int]] = None,
        preserve_aspect: bool = True,
        play_on_start: bool = True,
        start_paused: bool = False,
        loop: bool = True,
        max_loops: Optional[int] = None,
        speed: float = 1.0,
        fallback_image: Optional[Union[str, Image.Image]] = None,
        light_variant: Optional[Union[str, bytes, Image.Image]] = None,
        dark_variant: Optional[Union[str, bytes, Image.Image]] = None,
        anchor: str = "center",
        **kwargs,
    ):
        super().__init__(master=master, text="", anchor=anchor, **kwargs)

        # config
        self._source = source
        self._size = size
        self._preserve_aspect = preserve_aspect
        self._loop = loop
        self._max_loops = max_loops
        self._speed = max(0.01, float(speed))
        self._fallback = fallback_image
        self._light_variant = light_variant
        self._dark_variant = dark_variant

        # state
        self._frames: List[ImageTk.PhotoImage] = []
        self._durations: List[int] = []
        self._frame_index = 0
        self._playing = False
        self._after_id: Optional[str] = None
        self._loops_done = 0

        # Load source if provided
        if self._source:
            try:
                self.load(self._source)
            except Exception:
                if self._fallback:
                    self._load_fallback(self._fallback)

        # Start if requested
        if play_on_start and not start_paused:
            self.play()

    # --- loading ---
    def load(self, source: Union[str, bytes, Image.Image]):
        """Load GIF (or static image) from path/bytes/PIL.Image."""
        self.stop()
        self._frames.clear()
        self._durations.clear()
        self._frame_index = 0
        self._loops_done = 0

        if isinstance(source, Image.Image):
            pil = source.copy()
        elif isinstance(source, (bytes, bytearray)):
            pil = Image.open(io.BytesIO(source))
        elif isinstance(source, str):
            pil = Image.open(source)
        else:
            raise TypeError("source must be str, bytes, or PIL.Image")

        # Detect number of frames
        n_frames = getattr(pil, "n_frames", 1)

        for i in range(n_frames):
            try:
                pil.seek(i)
            except EOFError:
                break

            frame = pil.convert("RGBA")
            if self._size:
                frame = self._resize_frame(frame)
            self._frames.append(ImageTk.PhotoImage(frame))

            duration = pil.info.get("duration", 100)
            self._durations.append(max(1, int(duration)))

        if not self._frames:
            raise ValueError("No frames found in image")

        self.configure(image=self._frames[0])

    def _resize_frame(self, frame: Image.Image) -> Image.Image:
        if not self._size:
            return frame
        w, h = self._size
        if self._preserve_aspect:
            fw, fh = frame.size
            scale = min(w / fw, h / fh)
            new_size = (int(fw * scale), int(fh * scale))
            return frame.resize(new_size, RESAMPLE_LANCZOS)
        return frame.resize((w, h), RESAMPLE_LANCZOS)

    def _load_fallback(self, fallback: Union[str, Image.Image]):
        try:
            if isinstance(fallback, str):
                img = Image.open(fallback).convert("RGBA")
            else:
                img = fallback.convert("RGBA")
            if self._size:
                img = self._resize_frame(img)
            tk_img = ImageTk.PhotoImage(img)
            self._frames = [tk_img]
            self._durations = [0]
            self.configure(image=tk_img)
        except Exception:
            self._frames = []
            self._durations = []

    # --- animation ---
    def play(self):
        if not self._frames or self._playing:
            return
        self._playing = True
        self._animate()

    def pause(self):
        self._playing = False
        self._cancel_after()

    def stop(self):
        self._playing = False
        self._cancel_after()
        self._frame_index = 0
        self._loops_done = 0
        if self._frames:
            self.configure(image=self._frames[0])

    def toggle(self):
        if self._playing:
            self.pause()
        else:
            self.play()

    def _animate(self):
        if not self._playing or not self._frames:
            return

        self._frame_index = (self._frame_index + 1) % len(self._frames)
        self.configure(image=self._frames[self._frame_index])

        if self._frame_index == 0:
            self._loops_done += 1
            if self._max_loops and self._loops_done >= self._max_loops:
                self.stop()
                return
            if not self._loop:
                self.stop()
                return

        delay = int(self._durations[self._frame_index] / self._speed)
        self._after_id = self.after(max(1, delay), self._animate)

    def _cancel_after(self):
        if self._after_id:
            try:
                self.after_cancel(self._after_id)
            except Exception:
                pass
            self._after_id = None

    def destroy(self):
        self._cancel_after()
        self._frames.clear()
        super().destroy()
